  <div class="toast" id="toast" role="status" aria-live="polite"></div><div class="modal" id="endModal" hidden><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="endTitle"><h2 id="endTitle">结束本次视频通话？</h2><p>结束后将关闭摄像头、麦克风和屏幕共享，并返回消息中心。</p><div class="dialog-actions"><button class="stay" id="stayButton">继续通话</button><button class="leave" id="leaveButton">结束通话</button></div></div></div>
</template>

<script setup>
import { onMounted } from 'vue'

onMounted(() => {
  const contacts={hr:{name:'王雨晴',avatar:'王',company:'极氪智能科技有限公司 · 招聘 HR',title:'AI 产品经理 · 视频一面'},chen:{name:'陈晨',avatar:'陈',company:'北京智谱未来科技有限公司 · 招聘 HR',title:'NLP 算法工程师 · 视频沟通'},li:{name:'李静',avatar:'李',company:'蓝湖创新科技有限公司 · 招聘顾问',title:'UI/UX 设计师 · 视频沟通'}};
      const params=new URLSearchParams(location.search),conversation=params.get('conversation')||'hr',contact=contacts[conversation]||contacts.hr,byId=id=>document.getElementById(id);let cameraStream=null,micStream=null,displayStream=null,toastTimer,elapsed=0;
      byId('remoteName').textContent=contact.name;byId('remoteAvatar').textContent=contact.avatar;byId('remoteCompany').textContent=contact.company;byId('meetingTitle').textContent=contact.title;byId('participantAvatar').textContent=contact.avatar;byId('participantName').textContent=contact.name+'（主持人）';byId('participantCompany').textContent='招聘 HR · '+contact.company.split(' · ')[0];byId('chatSender').childNodes[0].nodeValue=contact.name+' ';
      function toast(text){byId('toast').textContent=text;byId('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId('toast').classList.remove('show'),2600)}
      function stopStream(stream){stream?.getTracks().forEach(track=>track.stop())}function updateMediaState(){const camera=Boolean(cameraStream),mic=Boolean(micStream);byId('myMediaState').textContent=camera&&mic?'摄像头和麦克风已开启':camera?'摄像头已开启 · 麦克风已关闭':mic?'摄像头已关闭 · 麦克风已开启':'摄像头和麦克风已关闭'}
      // 摄像头与麦克风分别申请权限，方便候选人独立控制。
      byId('cameraButton').addEventListener('click',async()=>{const button=byId('cameraButton');if(cameraStream){stopStream(cameraStream);cameraStream=null;byId('localVideo').srcObject=null;byId('localVideo').style.display='none';byId('localOff').style.display='grid';button.classList.add('off');button.title='打开摄像头';toast('摄像头已关闭');updateMediaState();return}if(!navigator.mediaDevices?.getUserMedia)return toast('当前浏览器不支持摄像头访问');try{button.disabled=true;cameraStream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});byId('localVideo').srcObject=cameraStream;byId('localVideo').style.display='block';byId('localOff').style.display='none';button.classList.remove('off');button.title='关闭摄像头';toast('摄像头已开启，仅在本机预览')}catch(error){toast(error.name==='NotAllowedError'?'未获得摄像头权限，请在浏览器中允许后重试':'摄像头暂时不可用，请检查设备')}finally{button.disabled=false;updateMediaState()}});
      byId('micButton').addEventListener('click',async()=>{const button=byId('micButton');if(micStream){stopStream(micStream);micStream=null;button.classList.add('off');button.title='打开麦克风';toast('麦克风已关闭');updateMediaState();return}if(!navigator.mediaDevices?.getUserMedia)return toast('当前浏览器不支持麦克风访问');try{button.disabled=true;micStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});button.classList.remove('off');button.title='关闭麦克风';toast('麦克风已开启')}catch(error){toast(error.name==='NotAllowedError'?'未获得麦克风权限，请在浏览器中允许后重试':'麦克风暂时不可用，请检查设备')}finally{button.disabled=false;updateMediaState()}});
      byId('shareButton').addEventListener('click',async()=>{if(displayStream){stopStream(displayStream);displayStream=null;byId('shareButton').classList.remove('active');byId('shareBanner').classList.remove('show');toast('已停止屏幕共享');return}if(!navigator.mediaDevices?.getDisplayMedia)return toast('当前浏览器不支持屏幕共享');try{displayStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});byId('shareButton').classList.add('active');byId('shareBanner').classList.add('show');displayStream.getVideoTracks()[0].addEventListener('ended',()=>{displayStream=null;byId('shareButton').classList.remove('active');byId('shareBanner').classList.remove('show');toast('已停止屏幕共享')});toast('屏幕共享已开始')}catch(error){if(error.name!=='NotAllowedError')toast('无法开始屏幕共享')}});
      function openPanel(name){byId('meeting').classList.add('has-panel');document.querySelectorAll('.panel-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.panel===name));byId('participantView').classList.toggle('hidden',name!=='participants');byId('chatView').classList.toggle('active',name==='chat');byId('participantButton').classList.toggle('active',name==='participants');byId('chatButton').classList.toggle('active',name==='chat');if(name==='chat')byId('chatInput').focus()}
      byId('participantButton').addEventListener('click',()=>openPanel('participants'));byId('chatButton').addEventListener('click',()=>openPanel('chat'));document.querySelectorAll('.panel-tab').forEach(tab=>tab.addEventListener('click',()=>openPanel(tab.dataset.panel)));byId('closePanel').addEventListener('click',()=>{byId('meeting').classList.remove('has-panel');byId('participantButton').classList.remove('active');byId('chatButton').classList.remove('active')});
      byId('chatForm').addEventListener('submit',event=>{event.preventDefault();const value=byId('chatInput').value.trim();if(!value)return;const message=document.createElement('div');message.className='chat-message';message.innerHTML='<b>林晓雨（我） <span class="chat-time">刚刚</span></b><p></p>';message.querySelector('p').textContent=value;byId('chatList').appendChild(message);byId('chatInput').value='';byId('chatList').scrollTop=byId('chatList').scrollHeight});
      byId('endButton').addEventListener('click',()=>{byId('endModal').hidden=false;byId('stayButton').focus()});byId('stayButton').addEventListener('click',()=>{byId('endModal').hidden=true;byId('endButton').focus()});byId('leaveButton').addEventListener('click',()=>{releaseMedia();window.__agentNavigate(`/agent/messages?conversation=${encodeURIComponent(conversation)}&call=ended`)});byId('endModal').addEventListener('click',event=>{if(event.target===byId('endModal'))byId('stayButton').click()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!byId('endModal').hidden)byId('stayButton').click()});
      function releaseMedia(){stopStream(cameraStream);stopStream(micStream);stopStream(displayStream);cameraStream=micStream=displayStream=null}window.addEventListener('beforeunload',releaseMedia);setInterval(()=>{elapsed++;const minutes=String(Math.floor(elapsed/60)).padStart(2,'0'),seconds=String(elapsed%60).padStart(2,'0');byId('timer').textContent=minutes+':'+seconds},1000);setTimeout(()=>toast('已进入视频面试，点击下方按钮开启设备'),500);
})
</script>

<style>
