px;border-top:1px solid var(--line)}.chat-compose input{min-width:0;flex:1;height:36px;padding:0 10px;border:1px solid #405066;border-radius:5px;outline:none;color:#fff;background:#182331}.chat-compose input:focus{border-color:var(--blue)}.chat-compose button{width:58px;border:0;border-radius:5px;color:#fff;background:var(--blue);cursor:pointer}.controls{grid-column:1;display:flex;align-items:center;justify-content:center;gap:8px;padding:9px 18px;border-top:1px solid #2C3849;background:var(--navy)}.control{width:68px;min-width:68px;height:62px;display:grid;place-items:center;align-content:center;gap:4px;border:0;border-radius:6px;color:#E9EEF5;background:transparent;cursor:pointer}.control:hover,.control.active{background:#2A394D}.control-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#33445A;font-size:16px}.control.off .control-icon{background:#873943}.control span:last-child{font-size:9px;white-space:nowrap}.control.end{width:82px;color:#fff}.control.end .control-icon{width:48px;border-radius:16px;background:var(--red)}.control.end:hover{background:transparent}.divider{width:1px;height:35px;margin:0 5px;background:#344155}.toast{position:fixed;z-index:80;top:76px;left:50%;max-width:min(480px,calc(100% - 32px));padding:10px 14px;border:1px solid #486078;border-radius:6px;color:#EEF4FC;background:#26374B;opacity:0;transform:translate(-50%,-8px);transition:.18s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal[hidden]{display:none}.modal{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:20px;background:rgba(4,9,15,.68)}.dialog{width:min(380px,100%);padding:24px;border:1px solid #465569;border-radius:8px;background:#202C3B;text-align:center;box-shadow:0 25px 60px rgba(0,0,0,.42)}.dialog h2{margin:0;font-size:18px}.dialog p{margin:8px 0 20px;color:var(--muted);font-size:12px}.dialog-actions{display:flex;gap:9px}.dialog-actions button{height:40px;flex:1;border-radius:6px;color:#fff;font-weight:700;cursor:pointer}.stay{border:1px solid #526178;background:#29384B}.leave{border:1px solid var(--red);background:var(--red)}button:focus-visible,input:focus-visible{outline:3px solid rgba(43,127,255,.35);outline-offset:2px}@media(max-width:850px){.meeting.has-panel{grid-template-columns:minmax(0,1fr) 280px}.local-tile{right:18px;width:180px}.remote-tile{width:100%;height:88%}.privacy-note{white-space:nowrap}}@media(max-width:650px){.meeting.has-panel{grid-template-columns:1fr}.side-panel{position:fixed;z-index:50;inset:58px 0 82px}.remote-tile{min-height:300px}.local-tile{right:12px;bottom:18px;width:145px}.controls{gap:2px;padding-inline:6px}.control{width:53px;min-width:53px}.control span:last-child{font-size:8px}.divider{display:none}.security,.meeting-meta{display:none}}
